import express from 'express';

const app = express();

// 1. Middleware de log: todo pedido passa aqui primeiro.
//    next() libera o pedido para o próximo passo do corredor.
app.use((req, res, next) => {
  console.log('pedido recebido:', req.method, req.url);
  next();
});

// 2. Middleware que transforma o corpo em JSON (express.json()).
//    Sem ele, req.body chega vazio nas rotas.
app.use(express.json());

// 3. Rota dinâmica: o :id aceita QUALQUER valor no caminho.
app.get('/usuarios/:id', (req, res) => {
  // req.params guarda os curingas da rota: { id: '7' }
  // req.query guarda o que veio depois do ?: { detalhes: 'true' }
  const resposta = { id: req.params.id, detalhes: req.query.detalhes ?? 'false' };
  res.json(resposta);
});

app.listen(3000);
